with with_gaps as (select *, case when lag(reading_ts) over (partition by device_code order by reading_ts, id) is null or reading_ts > lag(reading_ts) over (partition by device_code order by reading_ts, id) + interval '30' minute then 1 else 0 end as is_new_burst from device_readings), islands as (select id, device_code, reading_ts, temp_c, humidity, firmware, sum(is_new_burst) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_no from with_gaps) select id, device_code, reading_ts, humidity, firmware, session_no from islands order by humidity desc, id desc;
